// Step 1: Generate a code verifier (43-128 characters, high entropy)
const verifier = base64UrlEncode(crypto.getRandomValues(new Uint8Array(32)));

// Step 2: Create the code challenge (SHA256 + base64url)
const challenge = base64UrlEncode(
  crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier))
);

// Step 3: Authorization request includes code_challenge
GET https://auth.example.com/authorize?
  response_type=code
  &client_id=spa-client-id
  &redirect_uri=https://app.example.com/callback
  &code_challenge={challenge}
  &code_challenge_method=S256
  &state=abc123
  &scope=openid profile

// Step 4: Token exchange includes the verifier (not the challenge)
POST /oauth/token
  grant_type=authorization_code
  &code=AUTH_CODE
  &redirect_uri=https://app.example.com/callback
  &code_verifier={verifier}
  // Server hashes verifier and checks it matches the stored challenge

async function generatePKCEPair() {
  const array = new Uint8Array(32);
  crypto.getRandomValues(array);
  const verifier = base64UrlEncode(array);

  const challengeBuffer = await crypto.subtle.digest(
    'SHA-256',
    new TextEncoder().encode(verifier)
  );
  const challenge = base64UrlEncode(new Uint8Array(challengeBuffer));

  return { verifier, challenge };
}

function base64UrlEncode(buffer) {
  return btoa(String.fromCharCode(...buffer))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

app.MapPost("/oauth/token", async (TokenRequest req) =>
{
    if (req.GrantType != "authorization_code")
        return Results.BadRequest();

    // Retrieve the stored challenge from the authorization request
    var storedChallenge = await GetStoredChallengeAsync(req.Code);

    var verifierHash = SHA256.HashData(Encoding.UTF8.GetBytes(req.CodeVerifier));
    var computedChallenge = Convert.ToBase64String(verifierHash)
        .Replace('+', '-').Replace('/', '_').Replace("=", "");

    if (computedChallenge != storedChallenge)
        return Results.BadRequest(new { error = "invalid_grant" });

    // Issue tokens...
    var accessToken = GenerateAccessToken(req.Subject);
    return Results.Ok(new { access_token = accessToken, expires_in = 900 });
});
